use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap,process::{Command,Stdio},io::Read};
const R:&str="/tmp/zopro-g2-tree-c7a";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn main(){let r=Path::new(R);assert_eq!(read(r.join("native/result.json"))["status"],"complete");let c=r.join("context");fs::create_dir(&c).unwrap();for n in ["basis","keys","fixtures"]{fs::create_dir(c.join(n)).unwrap();}let mut pins=BTreeMap::new();
 for(name,n)in[("baseline",112),("candidate",117)]{assert_eq!(read(r.join(format!("native/{name}-core/tests.json")))["passed_tests"].as_array().unwrap().len(),n);let a=read(r.join(format!("native/{name}/artifacts.json")));for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let bin=a["binary"].as_str().unwrap();assert_eq!(hash(bin),a["binary_sha256"].as_str().unwrap());let out=format!("gt-{name}");fs::copy(bin,c.join(&out)).unwrap();pins.insert(format!("/usr/local/bin/{out}"),hash(bin));}
 for(src,name)in[(r.join("runner"),"gt-runner"),(Path::new("/home/ubuntu/src/zk-tools/zopro/xtask/target/release/xtask").to_path_buf(),"gt-xtask")]{fs::copy(&src,c.join(name)).unwrap();pins.insert(format!("/usr/local/bin/{name}"),hash(src));}
 let old=read("/tmp/zopro-g2-prefix-tree/cases.json");let mut cases=Vec::new();for original in old.as_array().unwrap(){let mut case=original.clone();for(field,folder,target)in[("image","basis","/gt-basis"),("key","keys","/gt-keys"),("request","fixtures","/gt-fixtures")]{let src=Path::new(original[field].as_str().unwrap());let basename=src.file_name().unwrap().to_str().unwrap();fs::copy(src,c.join(folder).join(basename)).unwrap();let dest=format!("{target}/{basename}");pins.insert(dest.clone(),hash(src));case[field]=json!(dest);}cases.push(case);}assert_eq!(cases.len(),2);save(c.join("cases.json"),&json!(cases));
 pins.insert("/usr/lib/linux-tools/6.8.0-147-generic/perf".into(),"2927eb0973fd937bdd417622531c95f1e6e19307a29c3e05a2c6198e12af6e56".into());
 let parent="sha256:0b79be0b9b5b9675622282a950bd87c8bb98ed092a6605c3a1cb426f6848e66b";
 let m=json!({"container_pins":pins,"environment":read("/tmp/zopro-grouping-module/production-source-manifest.json")["environment"],"design_sha256":hash(r.join("design.md")),"build_pins_sha256":hash(r.join("build-pins.json")),"parent_image_id":parent,"native_core_tests":{"baseline":112,"candidate":117},"inherited_field_tests":33,"SDK_proofs":0,"Gnark_exports":0,"prior_proof_count":5958,"adopted":false});save(c.join("manifest.json"),&m);
 let base="558215002830.dkr.ecr.eu-north-1.amazonaws.com/zolana-prover:bench-latest-c7a-profile-20261025";let o=Command::new("docker").args(["image","inspect",base,"--format","{{.Id}}"] ).output().unwrap();assert!(o.status.success());assert_eq!(String::from_utf8(o.stdout).unwrap().trim(),parent);
 fs::write(c.join("Dockerfile"),format!("FROM {base}\nCOPY gt-baseline gt-candidate gt-runner gt-xtask /usr/local/bin/\nCOPY basis /gt-basis\nCOPY keys /gt-keys\nCOPY fixtures /gt-fixtures\nCOPY manifest.json cases.json /gt/\nENTRYPOINT [\"/usr/local/bin/gt-runner\"]\n")).unwrap();let log=fs::File::create(r.join("docker-build.log")).unwrap();assert!(Command::new("docker").args(["build","--pull=false","-t","zopro-g2-tree-c7a:preflight"]).arg(c).stdout(Stdio::from(log.try_clone().unwrap())).stderr(Stdio::from(log)).status().unwrap().success());save(r.join("image-prepared.json"),&json!({"status":"built; no cloud resources","manifest":m}));println!("Exact-image component preflight ready");
}
